  <title>Terms Consent</title>
  <style>
    :root {
      color-scheme: dark;
      --color-bg: #0b1020;
      --color-surface: #11182b;
      --color-surface-2: #16213a;
      --color-text: #f3f7ff;
      --color-muted-text: #a9b6d3;
      --color-border: #2a3550;
      --color-accent: #7dd3fc;
      --color-accent-strong: #38bdf8;
      --color-danger: #fda4af;
      --color-success: #86efac;
      --color-focus: #fbbf24;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

