      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
    }

    body {
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #172341 0%, transparent 42%),
        linear-gradient(180deg, #0b1020 0%, #080d18 100%);
      color: var(--color-text);
      line-height: 1.5;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .card {
      width: min(100%, 460px);
      background: linear-gradient(180deg, rgba(22, 33, 58, 0.96), rgba(13, 19, 35, 0.98));
      border: 1px solid var(--color-border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.6rem, 3vw, 2rem);
      line-height: 1.1;
      letter-spacing: -0.02em;
    }

    .lead {
      margin: 0 0 24px;
      color: var(--color-muted-text);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      padding: 18px;
      border: 1px solid var(--color-border);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.02);
    }

    .checkbox-row {
      display: flex;
      gap: 12px;
      align-items: flex-start;
    }

    .checkbox-row input[type="checkbox"] {
      margin-top: 0.2rem;
      width: 1.1rem;
      height: 1.1rem;
      accent-color: var(--color-accent);
      flex: none;
    }

    .checkbox-label {
      display: inline-block;
      color: var(--color-text);
      font-weight: 600;
      cursor: pointer;
    }

    .required-indicator {
      color: var(--color-accent);
      margin-left: 0.2rem;
    }

    .helper-text,
    .error-text,
    .status-text {
      margin: 8px 0 0;
      font-size: 0.95rem;
    }

    .helper-text {
      color: var(--color-muted-text);
    }

    .error-text {
      color: var(--color-danger);
    }

    .status-text {
      color: var(--color-success);
      min-height: 1.5em;
    }

    .submit-button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      background: linear-gradient(180deg, var(--color-accent), var(--color-accent-strong));
      color: #04111f;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      box-shadow: 0 10px 24px rgba(56, 189, 248, 0.24);
    }

    .submit-button:hover {
      filter: brightness(1.03);
    }

    .submit-button:active {
      transform: translateY(1px);
    }

    :focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    [hidden] {
      display: none !important;
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-2: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-border: ButtonBorder;
        --color-accent: LinkText;
        --color-accent-strong: LinkText;
        --color-danger: CanvasText;
        --color-success: CanvasText;
        --color-focus: Highlight;
      }

      .card,
      .form-field,
      .submit-button {
        forced-color-adjust: auto;
        border-color: ButtonBorder;
      }

      .submit-button {
        background: ButtonFace;
        color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <main id="maincontent">
    <div id="app"></div>
  </main>

  <script>
    const state = {
      termsAccepted: false,
      error: "",
      submitted: false
    };

    function CheckboxField() {
      const describedBy = ["terms-help"];
      if (state.error) describedBy.push("terms-error");

      return `
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms"
              name="terms"
              type="checkbox"
              required
              ${state.termsAccepted ? "checked" : ""}
              ${state.error ? 'aria-invalid="true"' : ""}
              aria-describedby="${describedBy.join(" ")}"
            >
            <div>
              <label class="checkbox-label" for="terms">
                I agree to the terms of use<span class="required-indicator" aria-hidden="true">*</span>
              </label>
              <p id="terms-help" class="helper-text">Required to continue.</p>
              <p id="terms-error" class="error-text" ${state.error ? "" : "hidden"}>${state.error || ""}</p>
            </div>
          </div>
        </div>
      `;
    }

    function App() {
      return `
        <section class="card" aria-labelledby="title">
          <h1 id="title">Consent form</h1>
          <p class="lead">Please confirm your agreement before continuing.</p>
          <form id="consent-form" novalidate>
            ${CheckboxField()}
            <button class="submit-button" type="submit">Continue</button>
            <p class="status-text" id="form-status" role="status" aria-live="polite">${state.submitted ? "Consent saved." : ""}</p>
          </form>
        </section>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();
      bindEvents();
    }

    function bindEvents() {
      const form = document.getElementById("consent-form");
      const checkbox = document.getElementById("terms");

      checkbox.addEventListener("change", () => {
        state.termsAccepted = checkbox.checked;
        state.error = "";
        state.submitted = false;
        render();
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        state.termsAccepted = checkbox.checked;

        if (!state.termsAccepted) {
          state.error = "Error: You must agree to the terms of use.";
          state.submitted = false;
          render();
          document.getElementById("terms").focus();
          return;
        }

        state.error = "";
        state.submitted = true;
        render();
      });
    }

    render();
  </script>
</body>
</html>
