      errorText.textContent = "";
      errorText.hidden = true;
      checkbox.removeAttribute("aria-invalid");
      checkbox.setAttribute("aria-describedby", "terms-help");
    }

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        clearError();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        setError("Error: You must agree to the terms of use.");
        checkbox.focus();
        return;
      }

      clearError();
      statusText.textContent = "Consent saved.";
    });
  </script>
</body>
