  const ariaInvalid = await page.locator('#terms').getAttribute('aria-invalid');
  if (focused !== 'terms' || ariaInvalid !== 'true' || !errorText?.includes('Error:')) {
    console.log(JSON.stringify({ focused, ariaInvalid, errorText }));
    await browser.close();
    process.exit(1);
