 <body>
   <main id="maincontent">
     <div id="app"></div>
   </main>

   <script>
     function App() {
       return `
         <section class="card" aria-labelledby="title">
           <h1 id="title">Consent form</h1>
           <p class="lead">Please confirm your agreement before continuing.</p>
           <form id="consent-form" novalidate>
             <div class="form-field">
               <div class="checkbox-row">
                 <input
                   id="terms"
                   name="terms"
                   type="checkbox"
                   required
                   aria-describedby="terms-help"
                 >
                 <div>
                   <label class="checkbox-label" for="terms">
                     I agree to the terms of use<span class="required-indicator" aria-hidden="true">*</span>
                   </label>
                   <p id="terms-help" class="helper-text">Required to continue.</p>
                   <p id="terms-error" class="error-text" hidden></p>
                 </div>
               </div>
             </div>
             <button class="submit-button" type="submit">Continue</button>
             <p class="status-text" id="form-status" role="status" aria-live="polite"></p>
           </form>
         </section>
       `;
     }

     const app = document.getElementById("app");
     app.innerHTML = App();

     const form = document.getElementById("consent-form");
     const checkbox = document.getElementById("terms");
     const errorText = document.getElementById("terms-error");
     const statusText = document.getElementById("form-status");

     function setError(message) {
       errorText.textContent = message;
       errorText.hidden = false;
       checkbox.setAttribute("aria-invalid", "true");
       checkbox.setAttribute("aria-describedby", "terms-help terms-error");
       statusText.textContent = "";
     }

     function clearError() {
       errorText.textContent = "";
       errorText.hidden = true;
       checkbox.removeAttribute("aria-invalid");
       checkbox.setAttribute("aria-describedby", "terms-help");
     }

     checkbox.addEventListener("change", () => {
       if (checkbox.checked) {
         clearError();
       }
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         setError("Error: You must agree to the terms of use.");
         checkbox.focus();
         return;
       }

       clearError();
       statusText.textContent = "Consent saved.";
     });
   </script>
 </body>
 </html>

